#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^#.room' "$t" || { echo "header line gone"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking gone"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null)" ] || { echo "not found should print nothing to stdout"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >/dev/null 2>&1; [ $? = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null)" ] || { echo "usage should print nothing to stdout"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null | grep -q '^usage: cancel.sh ROOM DATE START' || { echo "usage text missing on stderr"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel in other-room case failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "other room's booking at same date and start removed"; fail=1; }
! grep -q '^aoi' "$t2" || { echo "target booking still there (other-room case)"; fail=1; }
rm -f "$t" "$t2"; exit $fail

